import pLimit from 'p-limit';

const limit = pLimit(8);              // at most 8 concurrent operations
const results = await Promise.all(
  urls.map((url) => limit(() => fetchWithRetry(url)))
);

// worker.js - main thread cannot use Atomics.wait
const state = new Int32Array(new SharedArrayBuffer(4));
state[0] = 8;                         // permits

function acquire() {
  while (true) {
    const n = Atomics.load(state, 0);
    if (n > 0 && Atomics.compareExchange(state, 0, n, n - 1) === n) return;
    Atomics.wait(state, 0, 0);        // sleep until a release notifies
  }
}
function release() {
  Atomics.add(state, 0, 1);
  Atomics.notify(state, 0, 1);
}
